{
  "name": "Zepto Q3 Outreach",
  "description": "Outbound to grocery-tech founders in Bengaluru",
  "status": "draft"
}

{
  "campaignId": "c3f2a1e0-1234-4abc-9def-0123456789ab",
  "name": "Zepto founder 4-touch sequence",
  "isActive": true,
  "steps": [
    {
      "stepNumber": 1,
      "channel": "email",
      "delayDays": 0,
      "subject": "Quick idea for Zepto's ops team",
      "body": "Hi Priya, saw Zepto crossed 300 dark stores...",
      "condition": "always"
    },
    {
      "stepNumber": 2,
      "channel": "linkedin_connection",
      "delayDays": 2,
      "condition": "if_no_reply"
    },
    {
      "stepNumber": 3,
      "channel": "linkedin_dm",
      "delayDays": 4,
      "body": "Hi Priya, following up from my email on rider routing...",
      "condition": "if_no_reply"
    },
    {
      "stepNumber": 4,
      "channel": "whatsapp",
      "delayDays": 7,
      "body": "Hi Priya, last note - happy to share the Blinkit case study.",
      "condition": "if_no_reply"
    }
  ]
}

{
  "message": "Draft a follow-up email for Priya Sharma at Zepto who opened my last email twice."
}

{
  "action": "reply",
  "replyBody": "Hi Priya, thanks for getting back to me. Happy to jump on a quick 20-minute call this week to walk you through how we're helping Indian D2C brands like Zepto scale outbound. Does Thursday 4pm IST work?"
}

{
  "name": "Mumbai D2C Founders",
  "description": "Founders of D2C brands in Mumbai targeted for Q3 outreach",
  "tags": ["d2c", "mumbai", "q3-2026"]
}
